+  /// re-connect finds a renamed entry instead of duplicating it (issue
+  /// #977).
+  CustomProvider? byBaseUrl(String baseUrl) {
+    for (final provider in _providers) {
+      if (provider.baseUrl == baseUrl) return provider;
+    }
+    return null;
