+              setState(
+                () => error =
+                    'Name "$name" is already used by ${clash.baseUrl} — '
+                    'pick another name',
+              );
+              return;
+            }
+            Navigator.of(dialogContext).pop(name);
+          }
+
+          return AlertDialog(
+            title: const Text('Name this CodeMie connection'),
+            content: Column(
+              mainAxisSize: MainAxisSize.min,
+              children: [
+                TextField(
