  if (existing != null) {
    final updated = CustomProvider(
      id: existing.id,
      name: existing.name,
      baseUrl: baseUrl,
      modelId: modelId,
    );
    await registry.update(updated);
    registry.rememberKey(updated.id, key);
  } else {
    final provider = await registry.add(
      name: name,
      baseUrl: baseUrl,
      modelId: modelId,
    );
    registry.rememberKey(provider.id, key);
  }

