/// Pushes the [ProviderEditorPage] in create mode and saves the result to
/// [registry] (definition + session key). Returns the added provider, or
/// null when cancelled. Shared by the Providers section, the
/// default-chat-model picker, and the media slot editor.
Future<CustomProvider?> pushProviderEditor(
  BuildContext context,
  ProviderRegistry registry, {
  required String title,
  ModelsEndpointFetcher? modelsFetcher,
}) async {
  final result = await pushFaPage<ProviderEditorResult>(
    context,
    ProviderEditorPage(
      title: title,
      registry: registry,
      modelsFetcher: modelsFetcher,
    ),
  );
  if (result == null || result.deleted) return null;
  return landProviderResult(registry, result);
}

/// Lands an editor result in [registry] (issue #977): the name already
/// belongs to an entry on the SAME endpoint updates that entry in place —
/// re-auth/re-connect semantics, the id (and with it every dropdown
/// selection) survives; anything else adds a new entry (a fresh name on a
/// shared endpoint is a second account). A name on a DIFFERENT endpoint
/// never reaches here — [_ProviderEditorPageState._save] rejects it. The
/// typed key is remembered either way.
Future<CustomProvider> landProviderResult(
  ProviderRegistry registry,
  ProviderEditorResult result,
) async {
  final existing = registry.byName(result.name);
  final CustomProvider provider;
  if (existing != null && existing.baseUrl == result.baseUrl) {
    provider = CustomProvider(
      id: existing.id,
      name: result.name,
      baseUrl: result.baseUrl,
      // An empty model id means "unchanged" on the update landing — a
      // re-auth-shaped re-add must not wipe the stored model.
      modelId: result.modelId.isEmpty ? existing.modelId : result.modelId,
      requiresKey: existing.requiresKey || result.apiKey.isNotEmpty,
      provenance: existing.provenance,
      kind: existing.kind,
    );
    await registry.update(provider);
  } else {
    provider = await registry.add(
      name: result.name,
      baseUrl: result.baseUrl,
      modelId: result.modelId,
    );
  }
  if (result.apiKey.isNotEmpty) {
    registry.rememberKey(provider.id, result.apiKey);
  }
  return provider;
}

/// The values collected by the [ProviderEditorPage].
///
/// [apiKey] is optional and write-only: when given it is remembered in
/// memory for the session (custom providers, see
/// [ProviderRegistry.rememberKey]) or written to the saved-keys store
/// (hosted presets) by the caller — the page itself stores nothing.
/// [deleted] marks the editor's Delete action (custom providers only).
final class ProviderEditorResult {
  /// Creates an editor result.
  const ProviderEditorResult({
    required this.name,
    required this.baseUrl,
    required this.modelId,
    required this.apiKey,
    this.deleted = false,
  });

  /// The Delete action result; all other fields are empty.
  const ProviderEditorResult.delete()
    : name = '',
      baseUrl = '',
      modelId = '',
      apiKey = '',
      deleted = true;

  /// Display name in the provider picker.
  final String name;

  /// OpenAI-compatible endpoint.
  final String baseUrl;

  /// Default model id (may be empty — a provider may have no model yet).
  final String modelId;

  /// The API key typed into the editor (may be empty = "keep/none").
  final String apiKey;

  /// True when the user chose Delete.
  final bool deleted;
}

