faui.ProviderEditorPage _keyBasedEditorPage(
  faui.AddProviderPreset preset,
  faui.ProviderPreset? presetMode,
  faui.ProviderRegistry registry,
) {
  final editable = presetMode == null;
  return faui.ProviderEditorPage(
    title: preset.name,
