        .firstOrNull;
    if (existing != null) {
      await registry.update(
        CustomProvider(
          id: existing.id,
          name: result.name,
          baseUrl: existing.baseUrl,
          modelId: result.modelId,
          provenance: existing.provenance,
          requiresKey: existing.requiresKey,
          kind: existing.kind,
