+                  autofocus: true,
+                  onSubmitted: (_) => submit(),
+                  decoration: const InputDecoration(labelText: 'Provider name'),
+                ),
+                if (error.isNotEmpty) ...[
+                  const SizedBox(height: 8),
+                  Text(
