  final baseUrl = '${credentials.apiUrl}/v1';
  final cookie = credentials.authToken;

  // Check for an existing provider (re-login keeps the same model).
  final existing = registry.providers
      .where((p) => p.baseUrl == baseUrl)
      .firstOrNull;

